const reading = msg.payload;

function escapeTagValue(value) {
    return String(value).replace(/[ ,=]/g, "\\$&");
}

function formatFieldValue(value) {
    if (typeof value === "number" && Number.isInteger(value)) {
        return `${value}i`;
    }
    return String(value);
}

const tags = [
    `device_id=${escapeTagValue(reading.device_id)}`,
    `protocol=${escapeTagValue(reading.protocol)}`,
    `message_type=${escapeTagValue(reading.message_type)}`,
].join(",");

const fields = [];
for (const m of reading.measurements || []) {
    if (m.value === null || m.value === undefined) continue;
    fields.push(`${m.name}=${formatFieldValue(m.value)}`);
}
if (reading.location) {
    fields.push(`lat=${reading.location.lat}`);
    fields.push(`lon=${reading.location.lon}`);
}

if (fields.length === 0) {
    node.warn(`reading ${reading.device_id}/${reading.message_type} at ${reading.timestamp} has no fields, dropping`);
    return null;
}

const epochSeconds = Math.floor(new Date(reading.timestamp).getTime() / 1000);
const line = `iot_reading,${tags} ${fields.join(",")} ${epochSeconds}`;

msg.url = "http://influxdb:8086/api/v2/write?org=iot&bucket=telemetry&precision=s";
msg.method = "POST";
msg.headers = {
    "Authorization": "Token devtoken-not-a-secret",
    "Content-Type": "text/plain; charset=utf-8"
};
msg.payload = line;
return msg;
